<?php require_once "config.php";$q=trim($_GET['q']??'');$x="%$q%";$st=db()->prepare("SELECT id,brand,name FROM products WHERE brand LIKE ? OR name LIKE ? LIMIT 8");$st->bind_param("ss",$x,$x);$st->execute();$rs=$st->get_result();while($p=$rs->fetch_assoc()):?><a href="#" onclick="addCompare(<?=$p['id']?>);return false"><?=e($p['brand'].' — '.$p['name'])?></a><?php endwhile;?>
<script>function addCompare(id){let h=document.getElementById('compareHidden');if([...h.querySelectorAll('input')].length>=4){alert('Maksimal 4 produk.');return;}let i=document.createElement('input');i.type='hidden';i.name='ids[]';i.value=id;h.appendChild(i);document.getElementById('compareSearch').value='';document.getElementById('compareResults').innerHTML='';}</script>